function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPxuIssues(
  query: Record<string, string | number | boolean>,
): Promise<PxuIssueListItem[]> {
  const res = await apiClient.get<BffResponse<PxuIssueListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPxuIssue(sttRec: string): Promise<PxuIssue> {
  const res = await apiClient.get<BffResponse<PxuIssue>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPxuIssue(body: PxuIssueWrite): Promise<PxuIssue> {
  const res = await apiClient.post<BffResponse<PxuIssue>>(BASE, body);
  return unwrap(res);
}

export async function updatePxuIssue(sttRec: string, body: PxuIssueWrite): Promise<PxuIssue> {
  const res = await apiClient.put<BffResponse<PxuIssue>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}

export interface ToolEquipmentHit {
  code: string;
  name: string;
  unit: string;
  accountCode?: string;
}

export async function listToolsEquipment(search: string): Promise<ToolEquipmentHit[]> {
  const res = await apiClient.get<BffResponse<{ items: ToolEquipmentHit[] }>>(
    `/master/tools-equipment?search=${encodeURIComponent(search)}&page=1&pageSize=20`,
  );
  return unwrap(res).items ?? [];
}
